// Shared helpers for the TradeSource practice site (loaded before app.js).
// Everything hangs off window.TS so the other scripts can use it without a
// build step or modules.

(function () {
  const DATA = window.TRADESOURCE_DATA;
  const TS = (window.TS = { DATA });

  TS.escapeHtml = function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, (c) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    })[c]);
  };

  // Artwork lives in /images and is generated by scripts/generate-images.js.
  TS.logoSrc = (m) => `/images/logo-${m.slug}.svg`;
  TS.productSrc = (p) => `/images/product-${p.slug}.svg`;
  TS.categorySrc = (cat) => `/images/category-${cat.slug}.svg`;

  TS.findManufacturer = (slug) => DATA.manufacturers.find((m) => m.slug === slug);
  TS.findProduct = (slug) => DATA.products.find((p) => p.slug === slug);

  TS.manufacturerPath = (m, section) => `/en/gb/manufacturer/${m.slug}/${m.id}/${section}`;
  TS.productPath = (p) => `/en/gb/product/${p.slug}/${p.id}/${p.listingId}`;

  // --- Category tree -----------------------------------------------------
  // Index every node by id, remembering the chain of nodes from the top down.
  TS.categoryIndex = {};
  (function walk(nodes, chain) {
    nodes.forEach((node) => {
      const here = chain.concat(node);
      TS.categoryIndex[node.id] = { node, chain: here };
      walk(node.children, here);
    });
  })(DATA.categories, []);

  // /en/gb/category/catalogue/<slug>/<slug>/.../<id of the last node>
  TS.categoryPath = (chain) =>
    `/en/gb/category/catalogue/${chain.map((n) => n.slug).join('/')}/${chain[chain.length - 1].id}`;

  // Ids of a node and everything beneath it (for "products in this category").
  TS.subtreeIds = function subtreeIds(node) {
    return [node.id].concat(...node.children.map(subtreeIds));
  };

  // Home > Categories > Catalogue > ...chain. Every crumb is a link except,
  // optionally, the last one (the page you are on).
  TS.breadcrumbs = function breadcrumbs(chain, { currentIsLink }) {
    const crumbs = [
      { text: 'Home', href: '/en/gb' },
      { text: 'Categories', href: '/en/gb/categories' },
      { text: 'Catalogue', href: '/en/gb/categories/catalogue' },
    ];
    chain.forEach((node, i) => {
      crumbs.push({ text: node.name, href: TS.categoryPath(chain.slice(0, i + 1)) });
    });
    return crumbs.map((c, i) => {
      const last = i === crumbs.length - 1;
      return !last || currentIsLink
        ? `<li><a href="${c.href}" data-spa>${TS.escapeHtml(c.text)}</a></li>`
        : `<li><span aria-current="page">${TS.escapeHtml(c.text)}</span></li>`;
    }).join('');
  };
})();
